+import { NextRequest, NextResponse } from 'next/server';
+import { cookies } from 'next/headers';
+import { createClient } from '@/lib/supabase/server';
+
+/**
+ * Points Management API
+ *
+ * GET - Get points transactions for a customer
+ * POST - Award points manually (admin action)
+ *
+ * Query params (GET):
+ * - customerId: string (required)
+ * - page: number
+ * - limit: number
+ */
+
+export async function GET(request: NextRequest) {
+  try {
+    const cookieStore = await cookies();
+    const supabase = createClient(cookieStore);
+
+    const { data: { user } } = await supabase.auth.getUser();
+    if (!user) {
+      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
+    }
+
+    const { data: merchant } = await supabase
+      .from('merchants')
+      .select('id')
+      .eq('user_id', user.id)
+      .single();
+
+    if (!merchant) {
+      return NextResponse.json({ error: 'Merchant not found' }, { status: 404 });
+    }
+
+    const { searchParams } = new URL(request.url);
+    const customerId = searchParams.get('customerId');
+    const page = parseInt(searchParams.get('page') || '1');
+    const limit = Math.min(parseInt(searchParams.get('limit') || '20'), 100);
+    const offset = (page - 1) * limit;
+
+    if (!customerId) {
+      return NextResponse.json({ error: 'customerId is required' }, { status: 400 });
+    }
+
+    const { data: transactions, error, count } = await supabase
+      .from('points_transactions')
+      .select('*', { count: 'exact' })
+      .eq('merchant_id', merchant.id)
+      .eq('customer_id', customerId)
+      .order('created_at', { ascending: false })
+      .range(offset, offset + limit - 1);
+
+    if (error) {
+      console.error('Error fetching transactions:', error);
+      return NextResponse.json({ error: 'Failed to fetch transactions' }, { status: 500 });
+    }
+
+    // Get customer's current balance
+    const { data: loyalty } = await supabase
+      .from('customer_loyalty')
+      .select('points_balance, lifetime_points, current_tier')
+      .eq('merchant_id', merchant.id)
+      .eq('customer_id', customerId)
+      .single();
+
+    return NextResponse.json({
+      transactions,
+      customerStats: loyalty || { points_balance: 0, lifetime_points: 0, current_tier: 'Bronze' },
+      pagination: {
+        page,
+        limit,
+        total: count || 0,
+        totalPages: Math.ceil((count || 0) / limit),
+      },
+    });
+  } catch (error) {
+    console.error('Points transactions GET error:', error);
+    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
+  }
+}
+
