+interface Review {
+    id: string;
+    product_id: string;
+    customer_name?: string;
+    customer_email: string;
+    rating: number;
+    title?: string;
+    body?: string;
+    status: 'pending' | 'approved' | 'rejected';
+    verified_purchase: boolean;
+    helpful_count: number;
+    merchant_response?: string;
+    merchant_response_at?: string;
+    created_at: string;
+    products?: {
+        name: string;
+        slug: string;
+    };
+}
+
+export default function ReviewsPage() {
+    const { toast } = useToast();
+    const { merchant } = useMerchant();
+    const [reviews, setReviews] = useState<Review[]>([]);
+    const [isLoading, setIsLoading] = useState(true);
+    const [statusFilter, setStatusFilter] = useState<string>('all');
+    const [searchQuery, setSearchQuery] = useState('');
+    const [selectedReview, setSelectedReview] = useState<Review | null>(null);
+    const [responseText, setResponseText] = useState('');
+    const [isUpdating, setIsUpdating] = useState(false);
+    const [showResponseDialog, setShowResponseDialog] = useState(false);
+
+    const fetchReviews = useCallback(async () => {
+        if (!merchant?.id) return;
+
+        setIsLoading(true);
+        try {
+            // Fetch reviews for this merchant's products
+            const response = await fetch(`/api/dashboard/reviews?status=${statusFilter}&search=${searchQuery}`);
+
+            if (!response.ok) {
+                throw new Error('Failed to fetch reviews');
+            }
+
+            const data = await response.json();
+            setReviews(data.reviews || []);
+        } catch (error) {
+            console.error('Error fetching reviews:', error);
+            toast({
+                title: 'Error',
+                description: 'Failed to load reviews.',
+                variant: 'destructive',
+            });
+        } finally {
+            setIsLoading(false);
+        }
+    }, [merchant?.id, statusFilter, searchQuery, toast]);
+
+    useEffect(() => {
+        fetchReviews();
+    }, [fetchReviews]);
+
+    const updateReviewStatus = async (reviewId: string, status: 'approved' | 'rejected') => {
+        setIsUpdating(true);
+        try {
+            const response = await fetch(`/api/reviews/${reviewId}`, {
+                method: 'PATCH',
+                headers: { 'Content-Type': 'application/json' },
+                body: JSON.stringify({ status }),
+            });
+
+            if (!response.ok) {
+                throw new Error('Failed to update review');
+            }
+
+            setReviews((prev) =>
+                prev.map((r) => (r.id === reviewId ? { ...r, status } : r))
+            );
+
+            toast({
+                title: status === 'approved' ? 'Review Approved' : 'Review Rejected',
+                description: `The review has been ${status}.`,
+            });
+        } catch (_error) {
+            toast({
+                title: 'Error',
+                description: 'Failed to update review status.',
+                variant: 'destructive',
+            });
+        } finally {
+            setIsUpdating(false);
+        }
+    };
+
+    const submitResponse = async () => {
+        if (!selectedReview) return;
+
+        setIsUpdating(true);
+        try {
+            const response = await fetch(`/api/reviews/${selectedReview.id}`, {
+                method: 'PATCH',
+                headers: { 'Content-Type': 'application/json' },
+                body: JSON.stringify({ merchant_response: responseText }),
+            });
+
+            if (!response.ok) {
+                throw new Error('Failed to submit response');
+            }
+
+            setReviews((prev) =>
+                prev.map((r) =>
+                    r.id === selectedReview.id
+                        ? { ...r, merchant_response: responseText, merchant_response_at: new Date().toISOString() }
+                        : r
+                )
+            );
+
+            setShowResponseDialog(false);
+            setSelectedReview(null);
+            setResponseText('');
+
+            toast({
+                title: 'Response Submitted',
+                description: 'Your response has been added to the review.',
+            });
+        } catch (_error) {
+            toast({
+                title: 'Error',
+                description: 'Failed to submit response.',
+                variant: 'destructive',
+            });
+        } finally {
+            setIsUpdating(false);
+        }
+    };
+
+    const deleteReview = async (reviewId: string) => {
+        if (!confirm('Are you sure you want to delete this review?')) return;
+
+        try {
+            const response = await fetch(`/api/reviews/${reviewId}`, {
+                method: 'DELETE',
+            });
+
+            if (!response.ok) {
+                throw new Error('Failed to delete review');
+            }
+
+            setReviews((prev) => prev.filter((r) => r.id !== reviewId));
+
+            toast({
+                title: 'Review Deleted',
+                description: 'The review has been permanently deleted.',
+            });
+        } catch (_error) {
+            toast({
+                title: 'Error',
+                description: 'Failed to delete review.',
+                variant: 'destructive',
+            });
+        }
+    };

